interface Priced {
	price: number;
}

class Book {
	constructor(
		public title: string,
		public price: number,
	) {}
}

function total(items: Priced[]): number {
	return items.reduce((sum, item) => sum + item.price, 0);
}

console.log(total([new Book("A", 10), { price: 5 }]));

